python3 - <<'PY'
from pathlib import Path
import re, numpy as np
base = Path('data/one_cache')
sessions = []
for p in base.rglob('*'):
    if p.is_dir():
        parts = p.relative_to(base).parts
        if len(parts) >= 5 and re.match(r'\d{4}-\d{2}-\d{2}', parts[3]):
            sessions.append(base.joinpath(*parts[:5]))
sessions = sorted(set(sessions))
trial_counts = []
cluster_counts = []
subject_set = set()
for s in sessions[:20]:
    parts = s.relative_to(base).parts
    if len(parts) >= 3:
        subject_set.add(parts[2])
    trial_file = None
    for cand in s.rglob('trials.intervals.npy'):
        trial_file = cand
        break
    if trial_file and trial_file.exists():
        try:
            trial_counts.append(np.load(trial_file, mmap_mode='r').shape[0])
        except Exception:
            pass
    for cand in s.rglob('clusters.channels.npy'):
        try:
            cluster_counts.append(np.load(cand, mmap_mode='r').shape[0])
        except Exception:
            pass
print('sample_subjects_count', len(subject_set))
print('sample_trial_counts', trial_counts[:20])
print('sample_cluster_counts', cluster_counts[:20])
if trial_counts:
    print('trial_count_mean_sample', float(np.mean(trial_counts)))
if cluster_counts:
    print('cluster_count_mean_sample', float(np.mean(cluster_counts)))
